actionCenter.switchWaveFormType:
({dataCenter, globalUtils}, eventParams) => { 
  switch (eventParams.params.val.title) {
      case 'OFDM':
          dataCenter.waveformType = 'OFDM'
          break;
      case 'QAM':
          dataCenter.waveformType = 'QAM'
          break;
      case 'PSK':
          dataCenter.waveformType = 'PSK'
          break;
      case '正弦波':
          dataCenter.waveformType = 'sineWave'
          break;
      default:
          dataCenter.waveformType = 'OFDM'
          break;
  }
}

actionCenter.watchWaveFormType:
({dataCenter, globalUtils}, eventParams) => { 
    console.log('watch', dataCenter, globalUtils, eventParams)
    let { showConsrellOrOFDMlable, waveformConfigs } = dataCenter
    dataCenter.useCenerate = false
    switch (eventParams.value) {
        case 'OFDM':
            dataCenter.OFDMLable = showConsrellOrOFDMlable.OFDM
            dataCenter.waveformConfigs = waveformConfigs.map(
              item => ( [5, 3].includes(item.name) ? { ...item, "visible": true } : { ...item, "visible": false })
            )
            break;
        case 'QAM':
            dataCenter.OFDMLable = showConsrellOrOFDMlable.Consrellation
            dataCenter.waveformConfigs = waveformConfigs.map(
              item => ( [4, 3].includes(item.name) ? { ...item, "visible": true } : { ...item, "visible": false })
            )
            break;
        case 'PSK':
            dataCenter.OFDMLable = showConsrellOrOFDMlable.Consrellation
            dataCenter.waveformConfigs = waveformConfigs.map(
              item => ( [2, 3].includes(item.name) ? { ...item, "visible": true } : { ...item, "visible": false })
            )
            break;
        case 'sineWave':
            dataCenter.OFDMLable = showConsrellOrOFDMlable.Consrellation
            dataCenter.waveformConfigs = waveformConfigs.map(
              item => ( [1].includes(item.name) ? { ...item, "visible": true } : { ...item, "visible": false })
            )
            break;
        default:
            dataCenter.OFDMLable = showConsrellOrOFDMlable.Consrellation
            break;
    }
}

actionCenter.addImpairment:
({dataCenter, globalUtils}, eventParams) => { 
  const { impairment } = dataCenter
  dataCenter.impairment = !impairment
}

actionCenter.OFDMtype:
({dataCenter, globalUtils}, eventParams) => { 
  let { waveformConfigs } = dataCenter
  switch (eventParams.newValue) {
        case 'QAM':
            dataCenter.waveformConfigs = waveformConfigs.map(
              item => {
                if([4].includes(item.name)){
                  return { ...item, "visible": true }
                }
                if([2].includes(item.name)){
                  return { ...item, "visible": false }
                }
                return item
              }
            )
            break;
        case 'PSK':
            dataCenter.waveformConfigs = waveformConfigs.map(
              item => {
                if([2].includes(item.name)){
                  return { ...item, "visible": true }
                }
                if([4].includes(item.name)){
                  return { ...item, "visible": false }
                }
                return item
              } 
            )
            break;
        default:
            dataCenter.waveformConfigs = waveformConfigs.map(
              item => ( [2, 4].includes(item.name) ? { ...item, "visible": false } : item)
            )
            break;
    }
}

