actionCenter.addSession:
async ({dataCenter, globalUtils}, eventParams) => { 
    const { importDesignFile ,openConfirmBox } = globalUtils
    const res = await importDesignFile()
    if(res.type === 'error'){
      openConfirmBox({
        title: '提示',
        message: "文件不一致"
      })
      return
    }
    if(res){
      dataCenter.waveformType = res.waveformType
      dataCenter.OFDMgridDataSource = res.OFDMgridDataSource
      dataCenter.constellationDataSource = res.constellationDataSource
      dataCenter.apectrumDataSource = res.apectrumDataSource
      dataCenter.timeScopeDataSource = res.timeScopeDataSource
      dataCenter.impairment = res.impairment
    }
}

actionCenter.saveSession:
({dataCenter, globalUtils}, eventParams) => { 
  const { exportDesignFile } = globalUtils
  let param = {
    waveformType: dataCenter.waveformType,
    OFDMgridDataSource: dataCenter.OFDMgridDataSource,
    constellationDataSource: dataCenter.constellationDataSource,
    apectrumDataSource: dataCenter.apectrumDataSource,
    timeScopeDataSource: dataCenter.timeScopeDataSource,
    impairment: dataCenter.impairment,
  }
  exportDesignFile(param)
}
